import random


def play(rng, switch):
    car = rng.randrange(3)
    pick = rng.randrange(3)
    host = rng.choice([d for d in range(3) if d != pick and d != car])
    if switch:
        pick = 3 - pick - host
    return pick == car


def simulate(n, switch, seed):
    if n < 1:
        raise ValueError('play at least one game')
    rng = random.Random(seed)
    return sum(play(rng, switch) for _ in range(n)) / n

