class Fixed:
    def __init__(self, car, pick, host):
        self.ints = [car, pick]
        self.host = host
    def randrange(self, n):
        return self.ints.pop(0)
    def choice(self, seq):
        assert self.host in seq, f'the host may open {seq}'
        return self.host

assert play(Fixed(2, 0, 1), True) is True and play(Fixed(2, 0, 1), False) is False
assert play(Fixed(1, 1, 2), True) is False and play(Fixed(1, 1, 0), False) is True
assert play(Fixed(0, 2, 1), True) is True

class Spy:
    def __init__(self, seed):
        import random
        self.r = random.Random(seed)
        self.seen = []
    def randrange(self, n):
        v = self.r.randrange(n)
        self.seen.append(v)
        return v
    def choice(self, seq):
        car, pick = self.seen[-2:]
        assert list(seq) == sorted(seq) and car not in seq and pick not in seq and len(seq) == (1 if car != pick else 2), f'car {car}, pick {pick}: offered {seq}'
        return self.r.choice(seq)

for seed in range(30):
    play(Spy(seed), seed % 2 == 0)

for n in (0, -5):
    try:
        simulate(n, True, 1)
    except ValueError:
        pass
    else:
        raise AssertionError(f'raise ValueError for n={n}')

