from fractions import Fraction


def exact_win(doors, opened, switch):
    if doors < 3 or not 0 <= opened <= doors - 2:
        raise ValueError('need at least 3 doors and 0 <= opened <= doors - 2')
    if not switch:
        return Fraction(1, doors)
    return Fraction(doors - 1, doors) * Fraction(1, doors - 1 - opened)

