from fractions import Fraction
for d, k, want in ((4, 1, Fraction(3, 8)), (4, 2, Fraction(3, 4)), (10, 8, Fraction(9, 10)), (100, 98, Fraction(99, 100)), (6, 3, Fraction(5, 12)), (5, 0, Fraction(1, 5))):
    got = exact_win(d, k, True)
    assert got == want, f'{d} doors, {k} opened, switching: {want}; got {got}'
for d in (3, 4, 7, 100):
    for k in range(d - 1):
        assert exact_win(d, k, False) == Fraction(1, d), 'staying wins 1/doors, whatever the host opens'
for d, k in ((1_000_003, 1), (10 ** 9 + 7, 12345), (2 ** 61 - 1, 3)):
    for switch, want in ((True, Fraction(d - 1, d) * Fraction(1, d - 1 - k)), (False, Fraction(1, d))):
        got = exact_win(d, k, switch)
        assert isinstance(got, Fraction) and got == want, f'{d} doors, {k} opened: exactly {want} (a float rounded back to a Fraction is not exact); got {got!r}'

from fractions import Fraction
from itertools import combinations
def enum(d, k, switch):
    total = Fraction(0)
    for car in range(d):
        for pick in range(d):
            goats = [x for x in range(d) if x != pick and x != car]
            opens = list(combinations(goats, k))
            for shown in opens:
                closed = [x for x in range(d) if x != pick and x not in shown]
                if not switch:
                    total += Fraction(1, d * d * len(opens)) * (pick == car)
                else:
                    total += Fraction(1, d * d * len(opens)) * Fraction(closed.count(car), len(closed))
    return total
for d in (3, 4, 5, 6):
    for k in range(d - 1):
        for switch in (False, True):
            assert exact_win(d, k, switch) == enum(d, k, switch), f'd={d}, opened={k}, switch={switch}: {enum(d, k, switch)}'

for d, k in ((2, 0), (1, 0), (3, 2), (3, -1), (3, -2), (10, -10), (5, 4), (0, 0)):
    for switch in (False, True):
        try:
            exact_win(d, k, switch)
        except ValueError:
            pass
        else:
            raise AssertionError(f'raise ValueError for doors={d}, opened={k}, switch={switch}')

